const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.image}</svg>`;
const button = (label, action, cls='', attrs='') => `<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const assetTemplates = [
  {id:'fei-eguchi',name:'江口',aliases:'江口',kind:'character',facts:'男，22岁，从东京来到小城的大学生。正在写英语专业毕业论文；初登场穿夏装，后有浴衣和学生服。',desc:'来自东京的22岁大学生，独自来到运河小城，在贝原家借住写毕业论文。观察细腻，初见安子时羞赧。',prompt:'22岁日本男性，夏装，青年学生气质，自然克制的表情。人物设定参考照，半身正面，中性背景。建议采用低饱和胶片色调；发型与五官由创作确定。',scenes:[2,8,16,41],demo:'assets/eguchi.jpg',missing:'发型、五官、身高未写明'},
  {id:'fei-yasuko',name:'贝原安子',aliases:'安子',kind:'character',facts:'19岁。初登场用围巾包头，手持装满杂草的畚箕，穿木屐。她是郁代的妹妹、志乃的孙女。',desc:'19岁的贝原安子，动作麻利，初次接待江口时笑盈盈。居住在河边的旧式家宅。',prompt:'19岁日本女性，围巾包头，木屐，手持装有杂草的畚箕。自然明快的神态，半身人物设定照，朴素夏日衣着。建议低饱和胶片色调；具体衣服和外貌需创作确认。',scenes:[7,8,11],demo:'assets/yasuko.jpg',missing:'具体发型、五官未写明'},
  {id:'fei-naoyuki',name:'贝原直之',aliases:'直之',kind:'character',facts:'28岁。入赘贝原家，是郁代的丈夫、安子的姐夫。第35场穿剪裁合体的白色夏和服，有高贵绅士风度。',desc:'28岁的贝原直之，郁代的丈夫。白色夏和服，神情温和，有绅士风度。',prompt:'28岁日本男性，剪裁合体的白色夏和服，高贵绅士风度。人物设定照，半身正面，中性背景。建议自然光、低饱和胶片色调；五官与发型由创作确定。',scenes:[21,35],demo:'assets/naoyuki.jpg',missing:'五官、发型未写明'},
  {id:'fei-ikuyo',name:'贝原郁代',aliases:'郁代',kind:'character',facts:'27岁。安子的姐姐，直之的妻子。第63场描述她有忧郁神情，美貌而略带羞怯。',desc:'27岁的贝原郁代，安子的姐姐、直之的妻子。忧郁而略带羞怯。',prompt:'27岁日本女性，忧郁神情，美貌、略带羞怯，人物设定照，半身正面。建议朴素夏装、柔和自然光、低饱和胶片色调；衣着不是剧本给定的事实。',scenes:[63],demo:'assets/ikuyo.jpg',missing:'服装、发型、五官待创作确认'},
  {id:'fei-saburo',name:'三郎',aliases:'三郎',kind:'character',facts:'18岁。操船，话不多。初见江口用疑虑的目光打量他；随后划船载江口与安子游运河。',desc:'18岁的操船少年三郎，寡言，初见江口时带着疑虑。',prompt:'18岁日本操船少年，神情沉静，人物设定照。建议朴素夏日工作衣着、半身正面、低饱和胶片色调；服装与五官由创作确定。',scenes:[29,30,31],demo:'assets/saburo.jpg',missing:'服装、发型、五官未写明'},
  {id:'fei-shino',name:'贝原志乃',aliases:'志乃',kind:'character',facts:'75岁，是安子的奶奶。第18场跪坐于幽暗的佛龛前，用一种特制支架支撑臂肘；表情木然。',desc:'75岁的贝原志乃，跪坐在幽暗的佛龛前，以特制支架支撑臂肘，表情木然。',prompt:'',scenes:[18],demo:'assets/ikuyo.jpg',missing:'外貌、服装与姿态的视觉方案待补充'},
  {id:'fei-street',name:'河岸街道',aliases:'运河街道',kind:'scene',facts:'顺着运河蜿蜒伸展。传统铺面包括绸缎庄、洗染作坊、装裱铺、点心店；高矮错落，拥挤排列在街路两侧，暮霭中显得迷离。',desc:'运河边蜿蜒的传统商业街，店铺密集而高矮错落，夏日暮霭中的古雅小城。',prompt:'日本运河小城，沿河蜿蜒的传统街道，绸缎庄、洗染作坊、装裱铺、点心店，高矮错落的旧式铺面。盛夏傍晚，暮霭，低饱和胶片色调，场景设定图，无主体人物。',scenes:[4],demo:'assets/canal.jpg',missing:'店铺立面与街道空间需创作确定'},
  {id:'fei-corridor',name:'贝原家长走廊',aliases:'长廊 套廊',kind:'scene',facts:'旧式住宅中的走廊曲曲弯弯。安子引路并拧亮一盏又一盏电灯。夜间套廊面向院落，院中黑暗树丛深处传来流水声。',desc:'贝原家弯曲延伸的木走廊，一盏盏电灯通向幽暗庭院，夜里能听见流水声。',prompt:'日本旧式家宅，曲折延伸的木质长走廊，隔扇，夜间，一盏盏昏黄电灯，廊外幽暗庭院与树丛。低饱和胶片色调，无主体人物。空间构造由创作确定。',scenes:[8,9,10],demo:'assets/hall.jpg',missing:'走廊布局未给出平面图'},
  {id:'fei-room',name:'贝原家二楼和室',aliases:'日本式房间 客房',kind:'scene',facts:'江口的二楼日本式房间，外有阳台。可以看到河水；房间里有桌子，江口在这里写论文。',desc:'江口借住的二楼日本式房间，与面向河水的阳台相连，是论文写作和对话反复发生的空间。',prompt:'日本旧式家宅二楼和室，书写用桌子，与面向运河的阳台相连。建议榻榻米、纸隔扇、柔和夏日自然光、低饱和胶片色调。具体陈设与室内布局由创作确定。',scenes:[12,19,41],demo:'assets/hall.jpg',missing:'榻榻米、陈设细节属于视觉建议'},
  {id:'fei-boathouse',name:'运河与船房',aliases:'船棚 水路',kind:'scene',facts:'石阶通向河边船棚。棚内有几条小船，其中一条小艇船篷形似房屋。运河河面有水藻，三郎划船前行。',desc:'小城运河与船棚，石阶通到水边。几条小船停泊，带屋形船篷的小艇驶过长有水藻的水面。',prompt:'日本运河小城，石阶通向木船棚，几条小船停泊，一条带房屋形船篷的小艇，水面漂有水藻，盛夏。建议低饱和胶片色调、柔和自然光，场景设定图。',scenes:[29,30,31,32],demo:'assets/canal.jpg',missing:'船棚、船篷构造待创作确定'},
];
function seed(){
  return {folders:[{id:'feishi',name:'废市'},{id:'practice',name:'其他创作'}],extracted:false,assets:[
    {id:'practice-eguchi',name:'江口',aliases:'江口',kind:'character',folder:'practice',source:'同名测试示例 · 非《废市》角色',desc:'独立的人物造型练习。用于验证同名角色不会混在一起。',prompt:'都市青年，现代西装，人物造型练习。',facts:'这是为了测试同名选择而创建的示例，与本剧角色没有关系。',scenes:[],demo:'assets/naoyuki.jpg',main:'p-eguchi-1',status:'ready',versions:[{id:'p-eguchi-1',image:'assets/naoyuki.jpg',created:'已有示例',demo:true,prompt:'现代人物造型练习'}]},
    {id:'practice-woman',name:'短发女性',aliases:'女性',kind:'character',folder:'practice',source:'人物造型练习',desc:'短发人物参考，独立于《废市》。',prompt:'人物造型练习',facts:'现有示例资产。',scenes:[],demo:'assets/yasuko.jpg',main:'p-woman-1',status:'ready',versions:[{id:'p-woman-1',image:'assets/yasuko.jpg',created:'已有示例',demo:true,prompt:'人物造型练习'}]}
  ],materials:[
    {id:'sample-hall',name:'木廊氛围参考',kind:'image',folder:'practice',image:'assets/hall.jpg',source:'场景参考示例',demo:true},
    {id:'sample-canal',name:'柳川运河参考',kind:'image',folder:'practice',image:'assets/canal.jpg',source:'场景参考示例',demo:true},
    {id:'sample-eguchi',name:'青年造型候选',kind:'image',folder:null,image:'assets/eguchi.jpg',source:'未整理素材示例',demo:true},
    {id:'sample-ikuyo',name:'人物光线参考',kind:'image',folder:null,image:'assets/ikuyo.jpg',source:'未整理素材示例',demo:true}
  ],canvas:{id:'canvas-1',name:'未命名画布',folder:'feishi',nodes:[],prompt:''},lastAsset:'fei-eguchi'};
}
let state;
try{state=JSON.parse(localStorage.getItem(KEY)) || seed();}catch{state=seed();}
for(const a of state.assets){if(a.status==='generating'){a.status='failed';a.error='演示中断了，可以重试。';}}
let screenplay=null, tab='materials', folder='all', filter='all', search='', kindFilter='all', editorVersion=null, batchRunning=false, toastTimer;
let uploadData=null, pickerQuery='', pickerFolder='all', pickerPurpose='canvas';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('浏览器存储空间不足，当前改动只保留到本次页面关闭。');return false;}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function asset(id){return state.assets.find(a=>a.id===id);}
function currentAsset(){return asset(state.lastAsset) || state.assets[0];}
function extractedAssets(){return [...new Set(assetTemplates.map(t=>state.reuseMap?.[t.id]||t.id))].map(asset).filter(Boolean);}
function mainVersion(a){return a?.versions.find(v=>v.id===a.main) || a?.versions[0];}
function folderName(id){return state.folders.find(f=>f.id===id)?.name || '未分类';}
function ready(a){return !!a.main && !!mainVersion(a);}
function status(a){return a.status==='generating'?'生成中':a.status==='failed'?'生成失败':ready(a)?'可引用':a.prompt.trim()?'待补图':'待补充';}
function statusClass(a){return a.status==='failed'?'failed':ready(a)?'ready':'pending';}
function allMaterials(){return [...state.materials,...state.assets.flatMap(a=>a.versions.map((v,i)=>({id:`version-${v.id}`,name:`${a.name} · v${i+1}`,kind:'image',folder:a.folder,image:v.image,source:a.source,desc:a.desc,assetId:a.id,versionId:v.id,demo:v.demo,main:v.id===a.main})))];}
function header(page){return `<header class="topbar"><a class="brand" href="#library">${icon('spark')}<span>IP Studio</span></a><nav class="nav" aria-label="原型页面"><a href="#library" class="${page==='library'?'active':''}">资产库</a><a href="#script" class="${page==='script'?'active':''}">剧本提取</a><a href="#editor" class="${page==='editor'?'active':''}">快速编辑</a><a href="#canvas" class="${page==='canvas'?'active':''}">画布</a></nav><div class="top-end"><span class="prototype-chip">交互原型 · 演示生成</span><span class="user-dot" aria-label="个人空间">我</span></div></header>`;}
function foot(){return `<div class="footnote"><span>原型数据保存在当前浏览器。所有生成均为演示，不调用模型、不扣积分。</span>${button(icon('reset')+'重置演示','reset','quiet compact')}</div>`;}
function stepper(n){return `<div class="stepper"><span class="${n===1?'current':''}"><b>1</b>提取剧本</span><span class="${n===2?'current':''}"><b>2</b>完善资产</span><span class="${n===3?'current':''}"><b>3</b>画布引用</span></div>`;}
function folderOptions(selected, includeAll=false){return `${includeAll?'<option value="all">全部文件夹</option>':''}<option value="" ${!selected?'selected':''}>未分类</option>${state.folders.map(f=>`<option value="${f.id}" ${f.id===selected?'selected':''}>${esc(f.name)}</option>`).join('')}`;}
function library(){
  const list=tab==='materials'?allMaterials():state.assets;
  const count=f=>list.filter(a=>f==='all'||(f==='unfiled'?!a.folder:a.folder===f)).length;
  return `${header('library')}<main class="main"><div class="page-head"><div><h1>个人资产库</h1><p>每次创作都留下来，下次打开画布还能找到。</p></div><div class="row">${button(icon('upload')+'上传素材','upload-library')}${button(icon('plus')+'新建画布','new-canvas','primary')}</div></div><div class="library-layout"><aside class="sidebar" aria-label="资产文件夹"><div class="folder-row ${folder==='all'?'active':''}"><button class="folder-link" data-action="folder" data-id="all">${icon('library')}<span>全部资产</span><small class="folder-count">${count('all')}</small></button></div><div class="folder-row ${folder==='unfiled'?'active':''}"><button class="folder-link" data-action="folder" data-id="unfiled">${icon('image')}<span>未分类</span><small class="folder-count">${count('unfiled')}</small></button></div><div class="sidebar-title">我的文件夹</div>${state.folders.map(f=>`<div class="folder-row ${folder===f.id?'active':''}"><button class="folder-link" data-action="folder" data-id="${f.id}">${icon('folder')}<span>${esc(f.name)}</span><small class="folder-count">${count(f.id)}</small></button><div class="folder-actions"><button class="icon-btn" data-action="folder-menu" data-id="${f.id}" aria-label="管理${esc(f.name)}文件夹">${icon('more')}</button></div></div>`).join('')}${button(icon('plus')+'新建文件夹','new-folder','quiet compact')}<div class="sidebar-note">文件夹由你整理。<br>同名资产独立保存，跨画布引用不需要复制。</div></aside><section class="library-content"><div class="script-entry"><div class="script-number">92<small>剧本场次</small></div><div class="grow"><h3>用《废市》走一遍创作流程</h3><p>${state.extracted?'本次已提取 6 位人物、4 组场景，继续完善后可在任意画布引用。':'先提取主要人物与场景，再补图、定主图，最后带进新画布。'}</p></div>${button(state.extracted?'继续完善 '+icon('arrow'):'提取剧本资产 '+icon('arrow'),state.extracted?'go-editor':'go-script')}</div><div class="tabs" role="tablist" aria-label="资产类型"><button class="tab ${tab==='materials'?'active':''}" role="tab" aria-selected="${tab==='materials'}" data-action="tab" data-tab="materials">全部素材<span class="count">${allMaterials().length}</span></button><button class="tab ${tab==='objects'?'active':''}" role="tab" aria-selected="${tab==='objects'}" data-action="tab" data-tab="objects">角色与场景<span class="count">${state.assets.length}</span></button></div><div class="toolbar"><label class="search">${icon('search')}<span class="sr-only">搜索资产</span><input id="library-search" placeholder="搜索名称、描述或来源" value="${esc(search)}"></label><select id="kind-filter" aria-label="筛选类型">${(tab==='objects'?[['all','全部类型'],['character','角色'],['scene','场景']]:[['all','图片素材']]).map(([v,t])=>`<option value="${v}" ${v===kindFilter?'selected':''}>${t}</option>`).join('')}</select>${tab==='objects'?`<button class="filter-btn ${filter==='all'?'active':''}" data-action="filter" data-filter="all">全部状态</button><button class="filter-btn ${filter==='pending'?'active':''}" data-action="filter" data-filter="pending">待完善</button><button class="filter-btn ${filter==='ready'?'active':''}" data-action="filter" data-filter="ready">可引用</button>`:''}<span class="result-label" id="result-label"></span></div><div class="asset-grid" id="asset-grid"></div>${foot()}</section></div></main>`;
}
function drawGrid(){
  let list=tab==='materials'?allMaterials():state.assets;
  list=list.filter(a=>(folder==='all'||(folder==='unfiled'?!a.folder:a.folder===folder))&&(kindFilter==='all'||a.kind===kindFilter)&&(filter==='all'||tab==='materials'||(filter==='ready'?ready(a):!ready(a)))&&`${a.name} ${a.aliases||''} ${a.desc||''} ${a.source}`.toLowerCase().includes(search.toLowerCase()));
  $('#result-label').textContent=`${folder==='all'?'全部资产':folder==='unfiled'?'未分类':folderName(folder)} · ${list.length} 项`;
  $('#asset-grid').innerHTML=list.length?list.map(a=>{
    const obj=tab==='objects',v=obj?mainVersion(a):a,img=v?.image;
    return `<article class="asset-card"><button class="card-open" data-action="${obj?'edit-asset':'material-detail'}" data-id="${a.id}"><div class="asset-visual">${img?`<img src="${esc(img)}" alt="${esc(a.name)}${v.demo?'的原型示意图片':''}" loading="lazy">`:`<div class="empty-visual">${icon(a.kind==='scene'?'scene':'person')}<span>${status(a)}</span></div>`}<span class="visual-top tag ${obj?statusClass(a):''}">${obj?status(a):a.main?'主图':'素材'}</span>${img&&v.demo?'<span class="visual-label">示意素材</span>':''}</div><div class="card-body"><h3>${esc(a.name)}</h3><div class="card-desc">${esc(obj?a.desc:a.source)}</div><div class="card-meta"><span>${esc(folderName(a.folder))}</span><span>${obj?(a.kind==='character'?'角色':'场景')+(a.versions.length?' · '+a.versions.length+' 版':''):'图片'}</span></div></div></button><button class="icon-btn card-menu" data-action="move-asset" data-id="${a.id}" data-object="${obj}" aria-label="整理${esc(a.name)}">${icon('more')}</button></article>`;
  }).join(''):`<div class="empty-state">${icon('folder')}<h3>${search?'没有找到匹配资产':'这里还没有资产'}</h3><p>${search?'试试人物简称、描述，或换一个文件夹。':'新生成的结果会保存在库里，也可以上传或从剧本提取。'}</p>${button('从《废市》提取','go-script')}</div>`;
}
function scriptPage(){return `${header('script')}<main class="main"><a class="back-link" href="#library">${icon('back')}返回资产库</a><div class="page-head"><div><h1>从剧本开始</h1><p>先建立角色与场景，再把形象逐个确定下来。</p></div></div>${stepper(1)}<div class="script-layout"><section class="panel script-reader" aria-label="废市剧本原文"><h2>《废市》</h2><div class="credits">编剧：内藤诚、千桂穗 · 翻译：叶克忠</div>${screenplay?screenplay.scenes.map(s=>`<div class="scene-block"><h3>${s.number}. ${esc(s.heading)}</h3><p>${esc(s.text.split('\n').slice(1).join('\n'))}</p></div>`).join(''):'<p class="muted">正在读取你提供的剧本…</p>'}</section><section class="panel script-config"><h2>先把核心资产建起来</h2><p class="muted small">这轮选取主要角色和常用空间，方便完整试走流程。剧本原文包含 92 场，本轮不是全片资产清单。</p><div class="extraction-scope"><div class="scope-row"><strong>6 位主要人物</strong><span class="muted small">年龄 · 身份 · 服装</span></div><p class="small muted">江口、安子、直之、郁代、三郎、志乃</p><div class="scope-row"><strong>4 组主要场景</strong><span class="muted small">合并同一空间</span></div><p class="small muted">河岸街道、长走廊、二楼和室、运河与船房</p></div><label class="field"><span>保存到文件夹</span><select id="extract-folder">${folderOptions('feishi')}</select></label><div class="callout">同名角色不会自动合并。提取后可选择已有角色，也可以保留为本剧的新角色。<br>剧本没有写明的外貌会标为待补充。</div>${button(state.extracted?'查看已提取的资产 '+icon('arrow'):'提取并开始完善 '+icon('arrow'),'extract','primary','id="extract-button"')}<p class="inspection-note">本原型使用基于真实剧本整理的固定提取结果；不调用 AI。</p></section></div>${foot()}</main>`;}
function editor(){
  if(!state.extracted)return `${header('editor')}<main class="main"><div class="empty-state">${icon('book')}<h3>先从《废市》提取资产</h3><p>主要角色与场景会带着剧本描述和出处进入这里。</p>${button('打开剧本','go-script','primary')}</div></main>`;
  const scoped=extractedAssets();
  let a=currentAsset();if(!a||!scoped.some(x=>x.id===a.id))a=scoped[0];
  if(!a)return scriptPage();state.lastAsset=a.id;
  const done=scoped.filter(ready).length;
  const origins=Object.entries(state.reuseMap||{}).filter(([,id])=>id===a.id).map(([id])=>state.extractionSources?.[id]).filter(Boolean);
  const provenance=origins.length?origins:[a];
  const v=a.versions.find(x=>x.id===editorVersion)||mainVersion(a)||a.versions.at(-1);editorVersion=v?.id;
  return `${header('editor')}<main class="main"><a class="back-link" href="#library">${icon('back')}返回资产库</a><div class="page-head"><div><div class="eyebrow">《废市》 / 本次提取</div><h1>把资产完善好</h1><p>先补描述与图片，确认主图后，所有画布都能引用。</p></div><div class="row">${button(icon('spark')+'一键补齐缺图','batch')}${button('新画布引用 '+icon('arrow'),'new-canvas','primary')}</div></div><div class="progress-summary"><span>已完善 <strong>${done}</strong> / ${scoped.length}</span><div class="progress-track"><i style="width:${done/scoped.length*100}%"></i></div><span class="muted">${batchRunning?'正在逐项生成，成功项会直接入库。':`${scoped.filter(x=>!ready(x)&&!x.prompt.trim()).length} 项还需要补充生成提示词`}</span>${scoped.some(x=>x.status==='failed')?button('重试失败项','retry-failed','quiet compact'):''}</div><select class="mobile-select" id="editor-select" aria-label="选择需要编辑的资产">${scoped.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${esc(x.name)} · ${status(x)}</option>`).join('')}</select><div class="editing-layout"><aside class="panel editor-list"><div class="list-heading">本次提取 · ${scoped.length} 项</div>${['character','scene'].map(k=>`<div class="list-group-label">${k==='character'?'主要人物':'主要场景'} · ${scoped.filter(x=>x.kind===k).length}</div>${scoped.filter(x=>x.kind===k).map(x=>`<button class="editor-item ${x.id===a.id?'active':''}" data-action="edit-asset" data-id="${x.id}"><span class="tiny-image">${mainVersion(x)?`<img src="${esc(mainVersion(x).image)}" alt="">`:icon(k==='scene'?'scene':'person')}</span><span class="grow"><span>${esc(x.name)}</span><span class="item-state ${x.status==='failed'?'failed':''}">${status(x)}</span></span>${ready(x)?icon('check'):''}</button>`).join('')}`).join('')}</aside><section class="panel preview-panel"><div class="preview-heading"><div><h2>${esc(a.name)}</h2><div class="stat-line"><span>${a.kind==='character'?'角色':'场景'}</span><span>${esc(folderName(a.folder))}</span><span>${a.versions.length} 个版本</span></div></div><span class="tag ${statusClass(a)}">${status(a)}</span></div>${origins.length?`<div class="callout" style="margin-bottom:15px">本轮提取：${origins.map(x=>esc(x.name)).join('、')} → 复用已有资产「${esc(a.name)}」。<br>正在编辑已有资产本身；剧本依据保留在下方。</div>`:''}<div class="main-image">${v?`<img src="${esc(v.image)}" alt="${esc(a.name)}${v.demo?'的原型示意图片':''}">${v.demo?'<span class="visual-label">原型示意，不代表实际生成效果</span>':''}`:`<div class="placeholder">${icon(a.kind==='scene'?'scene':'person')}<h3>还没有${a.kind==='character'?'确定形象':'场景主图'}</h3><p>剧本描述已带过来。你可以上传主图，或补充提示词后生成。</p></div>`}${a.status==='generating'?'<div class="overlay-state"><div class="stack"><span class="loading-mark"></span><span>正在演示生成…</span></div></div>':''}</div>${a.versions.length?`<div class="version-list">${a.versions.map((x,i)=>`<button class="version ${v?.id===x.id?'active':''}" data-action="version" data-id="${x.id}"><div class="version-thumb"><img src="${esc(x.image)}" alt="v${i+1}"></div><small>v${i+1}${x.id===a.main?' · 主图':''}${x.demo?' · 示意':''}</small></button>`).join('')}</div>`:''}<div class="version-actions"><div class="row wrap">${button(icon('upload')+'上传作为主图','upload-main','compact')}${!a.versions.length?button('使用已有'+(a.kind==='character'?'角色':'场景'),'reuse-dialog','quiet compact'):''}</div>${v&&v.id!==a.main?button(icon('check')+'设为主图','set-main','primary compact','data-id="'+v.id+'"'):v?'<span class="small muted">当前主图 · 可直接引用</span>':''}</div>${a.status==='failed'?`<div class="callout error" style="margin-top:15px">${esc(a.error)} ${button('重试','generate-one','quiet compact')}</div>`:''}${provenance.map(origin=>`<div class="source-panel"><h3>${icon('book')} 剧本依据${origins.length?' · '+esc(origin.name):''} <span class="muted">${esc(origin.source)}</span></h3><div class="source-facts">${esc(origin.facts)}<br><strong>待创作确认：</strong>${esc(origin.missing||'')}</div><div class="scene-links">${origin.scenes.map(n=>`<button class="scene-link" data-action="source" data-scene="${n}">第 ${n} 场 ${icon('arrow')}</button>`).join('')}</div></div>`).join('')}${origins.length?`<div class="source-panel"><h3>已有资产来源 · ${esc(a.source)}</h3><p class="source-facts">${esc(a.facts)}</p></div>`:''}</section><section class="panel form-panel"><h3>资产信息</h3><label class="field"><span>名称 <span class="muted small">允许同名</span></span><input id="asset-name" maxlength="50" value="${esc(a.name)}"></label><label class="field"><span>所在文件夹</span><select id="asset-folder">${folderOptions(a.folder)}</select></label><label class="field"><span>人物 / 场景描述</span><textarea id="asset-desc" rows="3" maxlength="1000">${esc(a.desc)}</textarea><div class="field-help">用于理解资产；不会改写原始剧本依据。</div></label><label class="field"><span>生成提示词</span><textarea id="asset-prompt" rows="4" maxlength="2000" placeholder="补充你想要的外貌、服装、光线与风格…">${esc(a.prompt)}</textarea><div class="field-help">预填内容含创作建议，可修改；非全部来自剧本。</div></label><div class="field"><span>参考素材 <span class="muted small">可选</span></span><button class="reference-upload" data-action="upload-reference">${a.reference?`<img src="${esc(a.reference)}" alt="已上传参考图">`:icon('plus')}<span>${a.reference?'替换参考图':'上传图片作为参考'}<small>上传参考图后，再根据提示词生成</small></span></button>${a.reference?button('移除参考图','remove-reference','quiet compact'):''}</div><div class="save-status" id="save-status">${icon('check')} 已自动保存</div><div class="generation-footer"><div class="row between"><span class="small">生成 1 张新版本</span><span class="small muted">演示报价 8 积分</span></div>${button(icon('spark')+(a.status==='generating'?'生成中…':ready(a)?'生成新版本':'生成主图'),'generate-one','primary',a.status==='generating'?'disabled':'')}<div class="field-help">第一张图自动成为主图。后续版本需你确认，已有画布引用保持原版。</div></div></section></div>${foot()}</main>`;
}
function genericEditor(a){const v=mainVersion(a);return `${header('editor')}<main class="main"><a href="#library" class="back-link">${icon('back')}返回资产库</a><div class="page-head"><div><h1>${esc(a.name)}</h1><p>${esc(a.source)} · ${esc(folderName(a.folder))}</p></div>${button('在画布引用','use-object','primary','data-id="'+a.id+'"')}</div><div class="script-layout"><section class="panel preview-panel"><div class="main-image"><img src="${esc(v.image)}" alt="${esc(a.name)}示意图"><span class="visual-label">示意素材</span></div><div class="source-panel"><h3>来源</h3><p class="source-facts">${esc(a.facts)}</p></div></section><section class="panel form-panel"><h3>资产信息</h3><label class="field"><span>名称</span><input id="asset-name" value="${esc(a.name)}" maxlength="50"></label><label class="field"><span>所在文件夹</span><select id="asset-folder">${folderOptions(a.folder)}</select></label><label class="field"><span>描述</span><textarea id="asset-desc" rows="4">${esc(a.desc)}</textarea></label><div class="save-status" id="save-status">${icon('check')} 已自动保存</div><p class="small muted">此资产独立保存；名字相同的其他角色不会自动合并。</p></section></div>${foot()}</main>`;}
function canvas(){const c=state.canvas;return `${header('canvas')}<main class="canvas-main"><div class="canvas-header"><div class="grow"><div class="eyebrow">CANVAS / ${esc(folderName(c.folder))}</div><h1>${esc(c.name)}</h1></div><div class="row wrap">${state.previousCanvases?.length?`<select id="canvas-switch" aria-label="切换画布"><option value="${c.id}">${esc(c.name)}</option>${state.previousCanvases.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select>`:''}<label for="canvas-folder">新资产保存到</label><select id="canvas-folder">${folderOptions(c.folder)}</select>${button(icon('plus')+'新建画布','new-canvas','compact')}</div></div><div class="canvas-layout"><section class="canvas-board" aria-label="可拖动的创作画布"><div class="canvas-workarea"><div class="canvas-tools">${button(icon('at')+'引用资产','open-picker','compact')}${button(icon('pen')+'重命名','rename-canvas','compact')}</div><div id="canvas-nodes"></div></div></section><aside class="canvas-composer"><h2>引用已有资产创作</h2><p>在提示词里输入 @，或从资产库选取。每次引用都会锁定具体版本。</p><div id="reference-chips"></div>${button(icon('at')+'从资产库选择','open-picker','mention-button')}<label class="field"><span>画面描述</span><textarea id="canvas-prompt" rows="5" placeholder="试试：@江口 在贝原家长走廊里，灯光一盏盏亮起…">${esc(c.prompt)}</textarea><div class="field-help">@ 会打开选择器，同名角色需明确选择。</div></label><div class="composer-actions">${button(icon('spark')+'演示生成画面 · 8 积分','canvas-generate','primary')}<span class="small muted">生成结果自动进入全部素材。</span></div><div class="canvas-note">你在资产库里更换主图后，这张画布仍然引用原版。可在节点上查看并主动更新。<br><br>可拖动节点顶部调整位置。</div><div class="footnote">${button('返回资产库','go-library','quiet compact')}</div></aside></div></main>`;}
function drawCanvas(){
  const c=state.canvas;
  $('#canvas-nodes').innerHTML=c.nodes.length?c.nodes.map(n=>{
    const a=asset(n.assetId), newer=a&&a.main!==n.versionId;
    return `<article class="canvas-node" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px"><div class="node-drag" data-drag="${n.id}">${icon('grip')}<span>${n.result?'生成结果':'资产引用'} · ${esc(n.versionName||'')}</span><button class="icon-btn" data-action="remove-node" data-id="${n.id}" aria-label="移除${esc(n.name)}节点">${icon('close')}</button></div><div class="node-image"><img src="${esc(n.image)}" alt="${esc(n.name)}${n.demo?'示意图':''}">${n.demo?'<span class="visual-label">示意素材</span>':''}</div><div class="node-info"><strong>${esc(n.name)}</strong><span class="muted">${esc(n.folderName)} · ${n.result?'已存入资产库':esc(n.source||'')}</span>${newer?`<div class="update-note">已有不同的主图 ${button('查看更新','update-node','quiet compact','data-id="'+n.id+'"')}</div>`:''}</div></article>`;
  }).join(''):`<div class="canvas-empty"><h2>从已有角色开始下一幕</h2><p>引用《废市》人物和场景，<br>资产会跨画布保留，角色不再重新建。</p></div>`;
  $('#reference-chips').innerHTML=`<div class="reference-chips">${c.nodes.filter(n=>!n.result).map(n=>`<div class="ref-chip"><img src="${esc(n.image)}" alt=""><div class="grow"><strong>@${esc(n.name)}</strong><span class="muted">${esc(n.folderName)} · ${esc(n.versionName)}</span></div><button class="icon-btn" data-action="remove-node" data-id="${n.id}" aria-label="移除${esc(n.name)}引用">${icon('close')}</button></div>`).join('')}</div>`;
}
function render(){
  const page=location.hash.slice(1).split('/')[0]||'library';
  $('#app').innerHTML=page==='script'?scriptPage():page==='editor'?(currentAsset()&&!extractedAssets().some(x=>x.id===currentAsset().id)?genericEditor(currentAsset()):editor()):page==='canvas'?canvas():library();
  if(page==='library')drawGrid();if(page==='canvas')drawCanvas();
}
function go(page){if(location.hash===`#${page}`)render();else location.hash=page;}
function showDialog(title,body,wide=false){const d=$('#dialog');d.className=wide?'wide':'';d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="关闭弹窗">${icon('close')}</button></div><div class="dialog-content">${body}</div>`;if(!d.open)d.showModal();}
function closeDialog(){$('#dialog').close();uploadData=null;}
function batchDialog(failedOnly=false){
  if(batchRunning)return toast('正在生成，请等待这一批完成。');
  const pending=extractedAssets().filter(a=>!ready(a)&&(failedOnly?a.status==='failed':true));
  if(!pending.length)return toast('缺图已补齐。想尝试不同方案，可在单个资产里生成新版本。');
  showDialog(failedOnly?'重试失败资产':'一键补齐缺图',`<p class="dialog-desc">只处理本次提取里还没有主图的资产，已有形象会保留。提示词还空着的资产需要先完善。</p><div class="batch-list">${pending.map(a=>`<div class="batch-row"><label><input class="batch-check" type="checkbox" value="${a.id}" ${a.prompt.trim()?'checked':'disabled'}>${esc(a.name)}</label><small>${a.prompt.trim()?'8 积分 / 张':'缺提示词，暂不生成'}</small></div>`).join('')}</div><div class="batch-total"><span id="batch-count"></span><strong id="batch-price"></strong></div><p class="field-help">以上是演示报价。本原型不调用模型、不扣积分，图片是预置示意素材。</p><label class="checkbox-line"><input type="checkbox" id="simulate-failure">演示其中一项失败，验证单项重试</label><div class="dialog-actions">${button('取消','close-dialog')}${button('开始演示生成','start-batch','primary')}</div>`);
  updateBatchPrice();
}
function updateBatchPrice(){const n=$('#dialog').querySelectorAll('.batch-check:checked').length;$('#batch-count').textContent=`共 ${n} 项 · ${n} 张图`;$('#batch-price').textContent=`${n*8} 演示积分`;$('#dialog [data-action=start-batch]').disabled=!n;}
async function generate(a,fail=false){
  const spec={prompt:a.prompt,reference:a.reference||null,image:a.reference||a.demo};
  a.status='generating';a.error=null;save();render();await delay(950);
  if(fail){a.status='failed';a.error='这项演示生成失败了。其他成功项已保存，可以单独重试。';}
  else{const v={id:uid('v'),image:spec.image,created:new Date().toLocaleString('zh-CN'),demo:true,prompt:spec.prompt,reference:spec.reference};a.versions.push(v);if(!a.main)a.main=v.id;a.status='ready';if(a.id===state.lastAsset)editorVersion=v.id;}
  save();render();
}
function picker(purpose='canvas'){
  pickerPurpose=purpose;pickerQuery='';pickerFolder='all';
  showDialog(purpose==='reuse'?'用已有角色替代':'引用资产',`<p class="dialog-desc">${purpose==='reuse'?'只有你明确选择后才复用同一角色；不会按名字自动合并。':'当前画布优先，其次是所选文件夹。看清来源，再选择具体版本。'}</p><div class="picker-toolbar"><label class="search">${icon('search')}<span class="sr-only">搜索要引用的资产</span><input id="picker-search" placeholder="搜索人物、简称或场景"></label><select id="picker-folder" aria-label="引用范围"><option value="all" selected>全部文件夹</option>${folderOptions(state.canvas.folder).replace(/ selected/g,'')}</select></div><div class="picker-list" id="picker-list"></div><p class="field-help">没有主图的资产不能引用，请先去快速编辑里补图。</p>`,true);drawPicker();
}
function drawPicker(){
  const c=state.canvas;const refs=new Set(c.nodes.map(n=>n.assetId));let list=state.assets.filter(a=>ready(a)&&(pickerPurpose!=='reuse'||a.kind===currentAsset()?.kind)&&`${a.name} ${a.aliases} ${a.desc} ${folderName(a.folder)} ${a.source}`.toLowerCase().includes(pickerQuery.toLowerCase())&&(pickerFolder==='all'||a.folder===(pickerFolder||null)));
  list.sort((a,b)=>(refs.has(b.id)*10+(b.folder===c.folder)*2)-(refs.has(a.id)*10+(a.folder===c.folder)*2));
  let previous='';$('#picker-list').innerHTML=list.length?list.map(a=>{
    const group=refs.has(a.id)?'当前画布':a.folder===c.folder?'所选文件夹 · '+folderName(c.folder):'其他资产';const heading=group!==previous?`<div class="picker-group">${esc(group)}</div>`:'';previous=group;
    const m=mainVersion(a);return `${heading}<div class="picker-row"><img src="${esc(m.image)}" alt="${esc(a.name)}${m.demo?'示意图':''}"><div class="grow"><strong>${esc(a.name)}</strong> <span class="tag">${esc(folderName(a.folder))}</span><p>${esc(a.desc.slice(0,80))}</p><p>${esc(a.source)}</p></div><select aria-label="${esc(a.name)}引用版本" data-version-for="${a.id}">${a.versions.map((v,i)=>`<option value="${v.id}" ${v.id===a.main?'selected':''}>v${i+1}${v.id===a.main?' · 主图':''}${v.demo?' · 示意':''}</option>`).join('')}</select>${button(pickerPurpose==='reuse'?'使用':'引用','pick','compact','data-id="'+a.id+'"')}</div>`;
  }).join(''):'<div class="empty-state"><h3>没有可引用的匹配资产</h3><p>可换个文件夹，或先完善本剧资产。</p></div>';
}
function addNode(a,v){
  const c=state.canvas;const duplicate=c.nodes.find(n=>n.assetId===a.id&&n.versionId===v.id);if(duplicate){toast('这版资产已在当前画布里。');return;}
  const n=c.nodes.length;c.nodes.push({id:uid('node'),assetId:a.id,versionId:v.id,versionName:'v'+(a.versions.indexOf(v)+1),name:a.name,image:v.image,demo:v.demo,folderName:folderName(a.folder),source:a.source,x:48+(n%3)*218,y:100+Math.floor(n/3)*285});save();
}
function newCanvasDialog(){showDialog('新建画布',`<p class="dialog-desc">资产库里的角色和场景会继续保留。在新画布里输入 @ 就能引用。</p><label class="field"><span>画布名称</span><input id="new-canvas-name" maxlength="60" value="${state.extracted?'废市 · 长廊初遇':'未命名画布'}"></label><label class="field"><span>新资产保存到</span><select id="new-canvas-folder">${folderOptions('feishi')}</select><p class="field-help">只影响这张画布后续新产出的素材，已有角色保持原来的文件夹。</p></label><div class="dialog-actions">${button('取消','close-dialog')}${button('创建并打开','create-canvas','primary')}</div>`);}
function uploadDialog(mode){uploadData=null;showDialog(mode==='library'?'上传素材':mode==='reference'?'上传参考素材':'上传作为主图',`<p class="dialog-desc">${mode==='main'?'图片会保存为新版本并成为主图，已有画布仍保留原引用。':mode==='reference'?'这张图只作为生成参考，不会直接替换主图。':'上传的图片会进入全部素材，可以在任意画布使用。'}</p><div class="upload-drop" id="upload-drop">${icon('upload')}<span>选择本地图片</span><small class="muted">JPG / PNG / WebP · 原型限 1 MB</small><input type="file" id="upload-file" accept="image/jpeg,image/png,image/webp" aria-label="选择本地图片"></div><div id="upload-error" class="field-help" role="status"></div>${mode==='library'?`<label class="field"><span>素材名称</span><input id="upload-name" maxlength="60" placeholder="给素材一个容易找的名字"></label><label class="field"><span>保存到</span><select id="upload-folder">${folderOptions(folder!=='all'&&folder!=='unfiled'?folder:null)}</select></label>`:''}<div class="dialog-actions">${button('取消','close-dialog')}${button(mode==='main'?'保存为主图':mode==='reference'?'保存参考图':'上传到资产库','save-upload','primary',`data-mode="${mode}" disabled`)}</div>`);}
function materialDetail(id){const m=allMaterials().find(x=>x.id===id);if(!m)return;showDialog(esc(m.name),`<img class="material-detail-image" src="${esc(m.image)}" alt="${esc(m.name)}"><div class="stat-line"><span>${esc(folderName(m.folder))}</span><span>${esc(m.source)}</span>${m.demo?'<span class="tag">示意素材</span>':''}</div><p class="dialog-desc" style="margin-top:15px">${m.assetId?'这是角色 / 场景的一版图片。所有版本都会保存在全部素材里，包括未设为主图的候选。':'这是一张独立素材，可直接放入画布。需要长期复用的人物身份，可提升为角色资产。'}</p><div class="dialog-actions">${m.assetId?button('编辑所属资产','edit-from-material','','data-id="'+m.assetId+'"'):button('设为角色资产','promote','','data-id="'+m.id+'"')}${button('放入当前画布','use-material','primary','data-id="'+m.id+'"')}</div>`);}
const actions={
  'go-library':()=>go('library'),'go-script':()=>go('script'),'go-editor':()=>{state.lastAsset=state.reuseMap?.['fei-eguchi']||'fei-eguchi';editorVersion=null;save();go('editor');},
  'close-dialog':closeDialog,
  'folder':el=>{folder=el.dataset.id;search='';render();},
  'tab':el=>{tab=el.dataset.tab;kindFilter='all';filter='all';search='';render();},
  'filter':el=>{filter=el.dataset.filter;render();},
  'new-folder':()=>showDialog('新建文件夹',`<label class="field"><span>文件夹名称</span><input id="folder-name" maxlength="40" placeholder="例如：新片筹备"></label><p class="field-help">普通文件夹可以组织不同画布的资产，同名角色仍然各自独立。</p><div class="dialog-actions">${button('取消','close-dialog')}${button('创建','create-folder','primary')}</div>`),
  'create-folder':()=>{const name=$('#folder-name').value.trim();if(!name)return toast('先填写文件夹名称。');if(state.folders.some(f=>f.name===name))return toast('已有这个名称的文件夹。');const f={id:uid('folder'),name};state.folders.push(f);folder=f.id;save();closeDialog();go('library');toast('文件夹已创建。');},
  'folder-menu':el=>{const f=state.folders.find(f=>f.id===el.dataset.id);showDialog('管理文件夹',`<label class="field"><span>文件夹名称</span><input id="rename-folder" maxlength="40" value="${esc(f.name)}"></label><p class="field-help">删除文件夹后，里面的资产会移到“未分类”，资产和画布引用仍然保留。</p><div class="dialog-actions">${button('删除文件夹','delete-folder','danger','data-id="'+f.id+'"')}${button('保存名称','save-folder','primary','data-id="'+f.id+'"')}</div>`);},
  'save-folder':el=>{const name=$('#rename-folder').value.trim();if(!name)return toast('文件夹名称不能为空。');if(state.folders.some(f=>f.name===name&&f.id!==el.dataset.id))return toast('已有这个名称的文件夹。');state.folders.find(f=>f.id===el.dataset.id).name=name;save();closeDialog();render();toast('名称已更新。');},
  'delete-folder':el=>{const id=el.dataset.id;for(const a of [...state.assets,...state.materials])if(a.folder===id)a.folder=null;if(state.canvas.folder===id)state.canvas.folder=null;state.folders=state.folders.filter(f=>f.id!==id);folder='unfiled';save();closeDialog();render();toast('文件夹已删除，资产移到未分类。');},
  'move-asset':el=>{const id=el.dataset.id;const m=el.dataset.object==='true'?asset(id):allMaterials().find(m=>m.id===id);showDialog('整理资产',`<p class="dialog-desc">${esc(m.name)}${m.assetId?' 属于一个角色或场景，移动时其所有版本会一起移动。':''}</p><label class="field"><span>移动到</span><select id="move-folder">${folderOptions(m.folder)}</select></label><div class="dialog-actions">${button('取消','close-dialog')}${button('移动','save-move','primary','data-id="'+id+'" data-object="'+el.dataset.object+'"')}</div>`);},
  'save-move':el=>{const m=el.dataset.object==='true'?asset(el.dataset.id):allMaterials().find(x=>x.id===el.dataset.id);const target=m.assetId?asset(m.assetId):state.assets.find(x=>x.id===m.id)||state.materials.find(x=>x.id===m.id);target.folder=$('#move-folder').value||null;save();closeDialog();render();toast('资产已移动，已有画布引用保留。');},
  'extract':async()=>{if(state.extracted){state.lastAsset=state.reuseMap?.['fei-eguchi']||'fei-eguchi';editorVersion=null;save();return go('editor');}const dest=$('#extract-folder').value||null;const b=$('#extract-button');b.disabled=true;b.innerHTML='<span class="loading-mark"></span> 正在整理剧本资产…';await delay(700);for(const t of assetTemplates){if(!asset(t.id))state.assets.push({...structuredClone(t),folder:dest,source:'《废市》剧本',main:null,status:'draft',versions:[]});}state.extracted=true;state.lastAsset='fei-eguchi';save();go('editor');toast('6 位人物、4 组场景已建立，重复打开不会新建一份。');},
  'edit-asset':el=>{state.lastAsset=el.dataset.id;editorVersion=null;save();go('editor');},
  'version':el=>{editorVersion=el.dataset.id;render();},
  'set-main':el=>{const a=currentAsset();a.main=el.dataset.id;a.status='ready';save();render();toast('主图已更新，已有画布仍保留引用版本。');},
  'batch':()=>batchDialog(), 'retry-failed':()=>batchDialog(true),
  'start-batch':async()=>{const ids=[...$('#dialog').querySelectorAll('.batch-check:checked')].map(e=>e.value);const fail=$('#simulate-failure').checked;closeDialog();batchRunning=true;for(let i=0;i<ids.length;i++)await generate(asset(ids[i]),fail&&i===0);batchRunning=false;render();toast(fail?'本批成功项已入库，失败项可单独重试。':'缺图已补齐，成功项已保存到个人资产库。');},
  'generate-one':async()=>{const a=currentAsset();if(a.status==='generating')return;if(!a.name.trim())return toast('先填写资产名称。');if(!a.prompt.trim()){$('#asset-prompt')?.focus();return toast('先补充生成提示词，再生成主图。');}await generate(a);toast(a.versions.length>1?'新版本已保存，确认满意后可设为主图。':'主图已保存，现在可以在新画布引用。');},
  'upload-library':()=>uploadDialog('library'),'upload-main':()=>uploadDialog('main'),'upload-reference':()=>uploadDialog('reference'),
  'remove-reference':()=>{delete currentAsset().reference;save();render();toast('参考图已移除。');},
  'save-upload':el=>{if(!uploadData)return;const image=uploadData.image,mode=el.dataset.mode;if(mode==='library'){const name=$('#upload-name').value.trim()||uploadData.name;state.materials.push({id:uid('material'),name,kind:'image',image,folder:$('#upload-folder').value||null,source:'我上传的',demo:false});}else if(mode==='reference'){currentAsset().reference=image;}else{const a=currentAsset(),v={id:uid('v'),image,created:new Date().toLocaleString('zh-CN'),demo:false,prompt:'手动上传主图'};a.versions.push(v);a.main=v.id;a.status='ready';editorVersion=v.id;}save();closeDialog();render();toast(mode==='main'?'上传图已成为主图，旧画布引用保留。':mode==='reference'?'参考图已保存，可继续编辑提示词。':'图片已进入资产库。');},
  'source':el=>{const s=screenplay?.scenes.find(s=>s.number===Number(el.dataset.scene));if(!s)return toast('剧本还在读取，请稍后再试。');showDialog('第 '+s.number+' 场 · '+esc(s.heading),`<p class="dialog-desc">《废市》 · 原文出处。提示词中的创作建议请自行确认。</p><div class="source-dialog-text">${esc(s.text.split('\n').slice(1).join('\n'))}</div>`);},
  'new-canvas':newCanvasDialog,
  'create-canvas':()=>{const name=$('#new-canvas-name').value.trim();if(!name)return toast('先填写画布名称。');if(state.canvas.nodes.length){state.previousCanvases=state.previousCanvases||[];state.previousCanvases.push(structuredClone(state.canvas));}state.canvas={id:uid('canvas'),name,folder:$('#new-canvas-folder').value||null,nodes:[],prompt:''};save();closeDialog();go('canvas');toast('新画布已打开，点击引用资产或输入 @。');},
  'rename-canvas':()=>showDialog('画布名称',`<label class="field"><span>名称</span><input id="canvas-name" maxlength="60" value="${esc(state.canvas.name)}"></label><div class="dialog-actions">${button('取消','close-dialog')}${button('保存','save-canvas-name','primary')}</div>`),
  'save-canvas-name':()=>{const name=$('#canvas-name').value.trim();if(!name)return toast('名称不能为空。');state.canvas.name=name;save();closeDialog();render();},
  'open-picker':()=>picker(),
  'pick':el=>{const a=asset(el.dataset.id),v=a.versions.find(v=>v.id===$('#dialog select[data-version-for="'+a.id+'"]').value);if(pickerPurpose==='reuse'){const original=currentAsset();if(original.id===a.id)return toast('这是同一个资产，请选择其他已有角色。');state.reuseMap=state.reuseMap||{};if(original.versions.length)return toast('只有尚未补图的提取项可以替换为已有资产。');state.reuseMap[original.id]=a.id;state.extractionSources=state.extractionSources||{};state.extractionSources[original.id]=structuredClone(original);state.assets=state.assets.filter(x=>x.id!==original.id);state.lastAsset=a.id;save();closeDialog();render();toast('本轮提取已引用已有资产，未复制角色。');return;}addNode(a,v);if(state.canvas.prompt.endsWith('@'))state.canvas.prompt=state.canvas.prompt.slice(0,-1)+'@'+a.name+' ';save();closeDialog();go('canvas');toast('已引用 '+a.name+' · '+folderName(a.folder)+' · v'+(a.versions.indexOf(v)+1));},
  'remove-node':el=>{state.canvas.nodes=state.canvas.nodes.filter(n=>n.id!==el.dataset.id);save();drawCanvas();},
  'update-node':el=>{const n=state.canvas.nodes.find(n=>n.id===el.dataset.id),a=asset(n.assetId),v=mainVersion(a);showDialog('更新引用版本',`<p class="dialog-desc">${esc(n.name)} 当前引用 ${esc(n.versionName)}。新的主图是 v${a.versions.indexOf(v)+1}，你可以主动替换。</p><img class="material-detail-image" src="${esc(v.image)}" alt="新主图"><div class="dialog-actions">${button('保留原版','close-dialog')}${button('更新这张画布','confirm-update','primary','data-id="'+n.id+'"')}</div>`);},
  'confirm-update':el=>{const n=state.canvas.nodes.find(n=>n.id===el.dataset.id),a=asset(n.assetId),v=mainVersion(a);Object.assign(n,{versionId:v.id,versionName:'v'+(a.versions.indexOf(v)+1),image:v.image,demo:v.demo});save();closeDialog();drawCanvas();toast('这张画布的引用已更新。');},
  'canvas-generate':async el=>{const refs=state.canvas.nodes.filter(n=>!n.result);if(!refs.length)return toast('先引用一个角色或场景，再演示生成。');if(!state.canvas.prompt.trim()){$('#canvas-prompt').focus();return toast('写一句画面描述后再生成。');}const targetCanvas=state.canvas;const refsSnapshot=structuredClone(refs);const prompt=targetCanvas.prompt;const dest=targetCanvas.folder;el.disabled=true;el.innerHTML='<span class="loading-mark"></span> 正在演示生成…';await delay(1200);const image=refsSnapshot.find(n=>asset(n.assetId)?.kind==='scene')?.image||refsSnapshot[0].image;const m={id:uid('material'),name:targetCanvas.name+' · 画面',kind:'image',folder:dest,image,source:'画布：'+targetCanvas.name,desc:prompt,refs:refsSnapshot.map(n=>({assetId:n.assetId,versionId:n.versionId})),demo:true};state.materials.push(m);targetCanvas.nodes.push({id:uid('node'),name:m.name,image,demo:true,folderName:folderName(dest),source:m.source,result:true,x:48+(targetCanvas.nodes.length%3)*218,y:100+Math.floor(targetCanvas.nodes.length/3)*285});save();render();toast('演示结果已自动进入全部素材。');},
  'material-detail':el=>materialDetail(el.dataset.id),
  'edit-from-material':el=>{state.lastAsset=el.dataset.id;editorVersion=null;closeDialog();save();go('editor');},
  'use-material':el=>{const m=allMaterials().find(x=>x.id===el.dataset.id);if(m.assetId){const a=asset(m.assetId);addNode(a,a.versions.find(v=>v.id===m.versionId));}else{const n=state.canvas.nodes.length;state.canvas.nodes.push({id:uid('node'),name:m.name,image:m.image,demo:m.demo,folderName:folderName(m.folder),source:m.source,materialId:m.id,versionName:'原素材',x:48+(n%3)*218,y:100+Math.floor(n/3)*285});save();}closeDialog();go('canvas');toast('素材已放入当前画布。');},
  'use-object':el=>{const a=asset(el.dataset.id);addNode(a,mainVersion(a));go('canvas');},
  'promote':el=>{const m=state.materials.find(m=>m.id===el.dataset.id);showDialog('设为角色资产',`<p class="dialog-desc">把这张素材作为角色的第一版主图。原素材仍会保留在全部素材里。</p><label class="field"><span>角色名称</span><input id="promote-name" maxlength="50" value="${esc(m.name)}"></label><label class="field"><span>角色描述</span><textarea id="promote-desc" rows="3" placeholder="补充这个角色的身份和特征"></textarea></label><div class="dialog-actions">${button('取消','close-dialog')}${button('建立角色','save-promote','primary','data-id="'+m.id+'"')}</div>`);},
  'save-promote':el=>{const m=state.materials.find(m=>m.id===el.dataset.id),name=$('#promote-name').value.trim();if(!name)return toast('请填写角色名称。');const v={id:uid('v'),image:m.image,demo:m.demo,prompt:'从素材建立角色',created:'已有素材'};const a={id:uid('character'),name,aliases:name,kind:'character',folder:m.folder,source:m.source,desc:$('#promote-desc').value,prompt:'',facts:'从个人素材建立的角色。',scenes:[],versions:[v],main:v.id,status:'ready',demo:m.image};state.assets.push(a);state.lastAsset=a.id;save();closeDialog();go('editor');toast('角色已建立，可以跨画布引用。');},
  'reuse-dialog':()=>picker('reuse'),
  'reset':()=>showDialog('重置演示',`<p class="dialog-desc">只清空这版原型在当前浏览器里的上传和编辑数据，并恢复初始示例。</p><div class="dialog-actions">${button('保留改动','close-dialog')}${button('重置这版原型','confirm-reset','danger')}</div>`),
  'confirm-reset':()=>{state=seed();editorVersion=null;tab='materials';folder='all';filter='all';search='';save();closeDialog();go('library');toast('已恢复初始演示。');},
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const handler=actions[el.dataset.action];if(handler){e.preventDefault();Promise.resolve(handler(el)).catch(err=>{console.error(err);toast('这一步遇到问题，请重试。');});}});
document.addEventListener('input',e=>{
  const el=e.target;if(el.id==='library-search'){search=el.value;drawGrid();}
  if(el.id==='picker-search'){pickerQuery=el.value;drawPicker();}
  const fields={'asset-name':'name','asset-desc':'desc','asset-prompt':'prompt'};
  if(fields[el.id]){const a=currentAsset();if(!a)return;if(el.id==='asset-name'&&!el.value.trim()){ $('#save-status').textContent='名称不能为空'; return; }a[fields[el.id]]=el.value;const ok=save();$('#save-status').textContent=ok?'已自动保存':'当前改动只保留到页面关闭';}
  if(el.id==='canvas-prompt'){state.canvas.prompt=el.value;save();if(el.value.endsWith('@'))picker();}
});
document.addEventListener('change',async e=>{
  const el=e.target;
  if(el.id==='kind-filter'){kindFilter=el.value;drawGrid();}
  if(el.id==='asset-folder'){currentAsset().folder=el.value||null;save();render();}
  if(el.id==='editor-select'){state.lastAsset=el.value;editorVersion=null;save();render();}
  if(el.id==='canvas-switch'){const target=state.previousCanvases.find(c=>c.id===el.value);if(target){state.previousCanvases=state.previousCanvases.filter(c=>c.id!==target.id);state.previousCanvases.push(state.canvas);state.canvas=target;save();render();}}
  if(el.id==='canvas-folder'){state.canvas.folder=el.value||null;save();render();toast('后续新产出将保存到'+folderName(state.canvas.folder)+'。');}
  if(el.id==='picker-folder'){pickerFolder=el.value;drawPicker();}
  if(el.classList.contains('batch-check'))updateBatchPrice();
  if(el.id==='upload-file'){
    const f=el.files[0];if(!f)return;
    if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>1024*1024){$('#upload-error').textContent='请选择 1 MB 以内的 JPG、PNG 或 WebP 图片。';el.value='';return;}
    const reader=new FileReader();reader.onload=()=>{uploadData={image:reader.result,name:f.name.replace(/\.[^.]+$/,'')};$('#upload-drop').innerHTML=`<img class="upload-preview" src="${esc(reader.result)}" alt="上传预览"><span class="small">${esc(f.name)}</span>${button('重新选择','reselect-upload','compact')}`;if($('#upload-name'))$('#upload-name').value=uploadData.name;$('#upload-error').textContent='';$('#dialog [data-action=save-upload]').disabled=false;};reader.onerror=()=>{$('#upload-error').textContent='无法读取这张图片，请重新选择。';};reader.readAsDataURL(f);
  }
});
actions['reselect-upload']=()=>{const mode=$('#dialog [data-action=save-upload]').dataset.mode;uploadDialog(mode);};
let dragging=null;
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-drag]');if(!handle||e.target.closest('button'))return;const n=state.canvas.nodes.find(n=>n.id===handle.dataset.drag);if(!n)return;dragging={id:n.id,sx:e.clientX,sy:e.clientY,x:n.x,y:n.y};handle.setPointerCapture(e.pointerId);e.preventDefault();});
document.addEventListener('pointermove',e=>{if(!dragging)return;const n=state.canvas.nodes.find(n=>n.id===dragging.id);n.x=Math.max(0,dragging.x+e.clientX-dragging.sx);n.y=Math.max(70,dragging.y+e.clientY-dragging.sy);const el=$(`[data-node="${n.id}"]`);if(el){el.style.left=n.x+'px';el.style.top=n.y+'px';}});
document.addEventListener('pointerup',()=>{if(dragging){dragging=null;save();}});
window.addEventListener('hashchange',()=>{closeDialog();render();window.scrollTo(0,0);});
const layoutQuery=matchMedia('(min-width: 960px)');layoutQuery.addEventListener('change',e=>{document.documentElement.dataset.layout=e.matches?'desktop':'mobile';});
render();
fetch('screenplay.json').then(r=>{if(!r.ok)throw Error('剧本读取失败');return r.json();}).then(data=>{screenplay=data;if(location.hash==='#script')render();}).catch(()=>toast('剧本文件没有读取成功，请通过本地预览服务打开。'));
